'use strict';

// Verifies the schema against a REAL MySQL, both ways round.
//
// WHY THIS EXISTS. `schema.sql` is generated by replaying migrations/ against a
// MODEL of MySQL DDL. A model is a theory about what MySQL does, and every
// theory here was wrong in at least one place:
//
//   * a column the migration had to backtick (`trigger`, a reserved word) came
//     out bare, so the file was a syntax error from that line on — since
//     migration 065, and nothing noticed because nothing loaded it;
//   * dropping a column left its index behind, naming a column that no longer
//     existed;
//   * renaming a column did not rename it inside the indexes over it;
//   * dropping a foreign key removed the index MySQL leaves behind;
//   * and `IF(EXISTS(…), 'ALTER …', 'DO 0')` was read as a number rather than
//     as SQL, so four guarded index renames were silently never applied.
//
// Every one of those is invisible without a database. `node --test` checks that
// schema.sql matches the model; only MySQL can say whether the model matches
// MySQL. This is the difference between "the snapshot is up to date" and "the
// snapshot is right".
//
// It is NOT part of `npm test`, because the suite must run with no services.
// Run it wherever a MySQL is available:
//
//   DB_HOST=127.0.0.1 DB_PORT=3306 DB_USER=root DB_PASSWORD=secret \
//     node scripts/verify-schema-against-mysql.js
//
// It creates two scratch databases, applies the migration chain to one and
// schema.sql to the other, and compares every column, index and foreign key.
// Both are dropped afterwards, on success or failure.

const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const mysql = require('mysql2/promise');

const ROOT = path.join(__dirname, '..');
const SCHEMA_PATH = path.join(ROOT, 'schema.sql');

const env = process.env;
const HOST = env.DB_HOST || '127.0.0.1';
const PORT = Number(env.DB_PORT || 3306);
const USER = env.DB_USER || 'root';
const PASSWORD = env.DB_PASSWORD || '';

// Named for the run, so a crashed run never collides with the next one and a
// leftover database is obviously scratch.
const STAMP = `${Date.now().toString(36)}${Math.floor(Math.random() * 1e6).toString(36)}`;
const MIGRATED = `be_verify_mig_${STAMP}`;
const SNAPSHOT = `be_verify_sch_${STAMP}`;

async function connect(database) {
  return mysql.createConnection({
    host: HOST, port: PORT, user: USER, password: PASSWORD, database, multipleStatements: true,
  });
}

// One row per column, index and foreign key — the shape a database HAS, read
// back from the server rather than from the text that produced it. That is the
// whole point: the server is the arbiter, not either file.
async function describe(conn, schema) {
  const [columns] = await conn.query(
    `SELECT TABLE_NAME t, COLUMN_NAME c, COLUMN_TYPE ty, IS_NULLABLE nu,
            COALESCE(COLUMN_DEFAULT, '~') de, EXTRA ex, ORDINAL_POSITION pos
       FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = ?
      ORDER BY TABLE_NAME, ORDINAL_POSITION`, [schema]
  );
  const [indexes] = await conn.query(
    `SELECT TABLE_NAME t, INDEX_NAME i, NON_UNIQUE nu,
            GROUP_CONCAT(CONCAT(COLUMN_NAME, ':', SEQ_IN_INDEX) ORDER BY SEQ_IN_INDEX) cols
       FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = ?
      GROUP BY TABLE_NAME, INDEX_NAME, NON_UNIQUE ORDER BY TABLE_NAME, INDEX_NAME`, [schema]
  );
  const [keys] = await conn.query(
    `SELECT k.CONSTRAINT_NAME n, k.TABLE_NAME t, k.COLUMN_NAME c,
            k.REFERENCED_TABLE_NAME rt, k.REFERENCED_COLUMN_NAME rc,
            r.DELETE_RULE dr, r.UPDATE_RULE ur
       FROM information_schema.KEY_COLUMN_USAGE k
       JOIN information_schema.REFERENTIAL_CONSTRAINTS r
         ON r.CONSTRAINT_SCHEMA = k.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME = k.CONSTRAINT_NAME
      WHERE k.CONSTRAINT_SCHEMA = ? AND k.REFERENCED_TABLE_NAME IS NOT NULL
      ORDER BY k.TABLE_NAME, k.CONSTRAINT_NAME, k.ORDINAL_POSITION`, [schema]
  );
  const line = (row) => Object.values(row).map((v) => (v === null ? '~' : String(v))).join('|');
  return {
    columns: new Map(columns.map((r) => [`${r.t}.${r.c}`, line(r)])),
    indexes: new Map(indexes.map((r) => [`${r.t}.${r.i}`, line(r)])),
    keys: new Map(keys.map((r) => [`${r.t}.${r.n}.${r.c}`, line(r)])),
  };
}

// What differs, said as three lists rather than one: something present in only
// one side is a different kind of mistake from something present in both and
// defined differently, and they are fixed in different places.
function diff(kind, a, b) {
  const problems = [];
  for (const [key, value] of a) {
    if (!b.has(key)) problems.push(`${kind} ${key}: in the MIGRATED database, missing from the SNAPSHOT`);
    else if (b.get(key) !== value) problems.push(`${kind} ${key}:\n    migrated: ${value}\n    snapshot: ${b.get(key)}`);
  }
  for (const key of b.keys()) {
    if (!a.has(key)) problems.push(`${kind} ${key}: in the SNAPSHOT, missing from the MIGRATED database`);
  }
  return problems;
}

async function main() {
  const admin = await connect(undefined);
  let failed = false;
  try {
    for (const db of [MIGRATED, SNAPSHOT]) {
      await admin.query(`CREATE DATABASE \`${db}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`);
    }

    // 1) The migration chain, run by the real runner rather than a copy of it.
    //    A chain that does not apply is the failure this catches first, and it
    //    is the one that took a server container down.
    console.info(`Applying migrations/ to ${MIGRATED} …`);
    execFileSync(process.execPath, [path.join(ROOT, 'src', 'migrate.js')], {
      cwd: ROOT,
      stdio: 'inherit',
      env: { ...env, DB_HOST: HOST, DB_PORT: String(PORT), DB_USER: USER, DB_PASSWORD: PASSWORD, DB_NAME: MIGRATED },
    });

    // 2) And again, to prove it is a no-op the second time. The runner records
    //    what it applied; a migration that is not guarded against a re-run takes
    //    the server down on the next deploy, because the container runs
    //    `migrate && server`.
    console.info('Re-running the migrations to check they are idempotent …');
    execFileSync(process.execPath, [path.join(ROOT, 'src', 'migrate.js')], {
      cwd: ROOT,
      stdio: 'inherit',
      env: { ...env, DB_HOST: HOST, DB_PORT: String(PORT), DB_USER: USER, DB_PASSWORD: PASSWORD, DB_NAME: MIGRATED },
    });

    // 3) The snapshot, loaded the way its own header tells people to load it.
    console.info(`Loading schema.sql into ${SNAPSHOT} …`);
    const snapshotConn = await connect(SNAPSHOT);
    try {
      await snapshotConn.query(fs.readFileSync(SCHEMA_PATH, 'utf8'));
    } catch (err) {
      // Reported here rather than as a setup failure: MySQL is working fine,
      // the file it was handed is not. That distinction is the whole finding —
      // a snapshot that does not load is a snapshot nobody has ever loaded.
      console.error(`\nschema.sql does not load into an empty database:\n  ${err && err.message}\n`);
      console.error('The migrations are the source of truth. Fix scripts/build-schema.js so the');
      console.error('model agrees with MySQL, then run: node scripts/build-schema.js\n');
      await snapshotConn.end().catch(() => {});
      throw Object.assign(new Error('schema.sql does not load'), { alreadyReported: true });
    }
    await snapshotConn.end();

    // 4) Compare what the server actually built.
    const conn = await connect(undefined);
    const [migrated, snapshot] = [await describe(conn, MIGRATED), await describe(conn, SNAPSHOT)];
    await conn.end();

    const problems = [
      // schema_migrations is bookkeeping the runner creates and the snapshot
      // deliberately leaves empty — its header says so.
      ...diff('column', strip(migrated.columns), strip(snapshot.columns)),
      ...diff('index', strip(migrated.indexes), strip(snapshot.indexes)),
      ...diff('foreign key', strip(migrated.keys), strip(snapshot.keys)),
    ];

    if (problems.length) {
      failed = true;
      console.error(`\nschema.sql does not match the migration chain — ${problems.length} difference(s):\n`);
      for (const p of problems) console.error(`  ${p}`);
      console.error('\nThe migrations are the source of truth. Fix scripts/build-schema.js so the');
      console.error('model agrees with MySQL, then run: node scripts/build-schema.js\n');
    } else {
      const tables = new Set([...migrated.columns.keys()].map((k) => k.split('.')[0]));
      console.info(`\nschema.sql matches the migration chain exactly — ${tables.size} tables, `
        + `${migrated.columns.size} columns, ${migrated.indexes.size} indexes, ${migrated.keys.size} foreign keys.\n`);
    }
  } finally {
    for (const db of [MIGRATED, SNAPSHOT]) {
      await admin.query(`DROP DATABASE IF EXISTS \`${db}\``).catch(() => {});
    }
    await admin.end().catch(() => {});
  }
  process.exit(failed ? 1 : 0);
}

const strip = (map) => new Map([...map].filter(([k]) => !k.startsWith('schema_migrations.')));

main().catch((err) => {
  if (err && err.alreadyReported) process.exit(1);
  console.error(`\nVerification could not run: ${err && err.message}\n`);
  console.error('It needs a MySQL it may create and drop databases on. For example:');
  console.error('  DB_HOST=127.0.0.1 DB_PORT=3306 DB_USER=root DB_PASSWORD=secret \\');
  console.error('    node scripts/verify-schema-against-mysql.js\n');
  process.exit(2);
});
